function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);

  // Book
  ctx.fillStyle = '#663300';
  ctx.fillRect(W/2 - 50, H/2 - 50, 100, 100);
  ctx.lineWidth = 3;
  ctx.strokeStyle = 'black';
  ctx.strokeRect(W/2 - 50, H/2 - 50, 100, 100);

  // Stick figure
  ctx.fillStyle = 'black';
  ctx.beginPath();
  ctx.arc(W/2 - 150, H/2, 20, 0, 2 * Math.PI);
  ctx.fill();
  ctx.beginPath();
  ctx.moveTo(W/2 - 150, H/2 + 20);
  ctx.lineTo(W/2 - 150, H/2 + 100);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 - 150, H/2 + 50);
  ctx.lineTo(W/2 - 100, H/2 + 70);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 - 150, H/2 + 50);
  ctx.lineTo(W/2 - 200, H/2 + 70);
  ctx.stroke();

  // Wisdom words
  ctx.font = '24px Arial';
  ctx.textAlign = 'center';
  ctx.textBaseline = 'top';
  ctx.fillStyle = 'black';
  ctx.fillText('Apply what you read', W/2, H/2 - 100 + 20 * Math.sin(t));

  // Lesson life applying
  ctx.font = '18px Arial';
  ctx.textAlign = 'left';
  ctx.textBaseline = 'top';
  ctx.fillStyle = 'black';
  ctx.fillText('Lessons:', W/2 + 60, H/2 - 40);
  ctx.fillText('1. Be consistent', W/2 + 60, H/2 - 20 + 10 * Math.sin(t));
  ctx.fillText('2. Stay focused', W/2 + 60, H/2 + 10 + 10 * Math.cos(t));
  ctx.fillText('3. Keep learning', W/2 + 60, H/2 + 40 + 10 * Math.sin(t));

  ctx.restore();
}
